// The capacity cards of the Providers page.
//
// One card per account, one row per window of the account. The numbers are
// the collector's account window gauges, read in one query; the card order,
// the names, the icons and the notes are the presentation the owner
// approved.
const CAPACITY_ACCOUNTS = [
  { account: 'claude', name: 'Claude', icon: '\u2733', background: '#d97757', foreground: '#fff', meta: 'subscription' },
  { account: 'codex', name: 'Codex', icon: '\u229b', background: '#e8e8e8', foreground: '#111', meta: 'subscription' },
  { account: 'ollama', name: 'Ollama', icon: '\u25c9', background: '#f2f2f2', foreground: '#111', meta: 'subscription' },
  { account: 'opencode-go', name: 'OpenCode Go', icon: '{}', background: '#2b2f3a', foreground: '#7dd3fc', meta: 'subscription' },
  { account: 'antigravity', name: 'Antigravity', icon: 'A', background: 'linear-gradient(135deg,#4f8cff,#c86bfa)', foreground: '#fff', meta: 'subscription' },
  { account: 'grok', name: 'Grok', icon: '\u2298', background: '#000', foreground: '#fff', meta: 'subscription' },
];

// The name an account is read by, when the approved list does not name it.
const CAPACITY_NAMES = {
  'cloudflare-workers-ai': 'Cloudflare',
  'cohere': 'Cohere',
  'deepseek': 'DeepSeek',
  'google': 'Google',
  'groq': 'Groq',
  'inception': 'Inception',
  'kilo': 'Kilo',
  'kilo-keyed': 'Kilo (keyed)',
  'mistral': 'Mistral',
  'nvidia': 'NVIDIA',
  'opencode': 'OpenCode Zen',
  'orcarouter': 'Orcarouter',
  'ovh': 'OVH',
  'pi': 'Pi',
  'poolside': 'Poolside',
  'requesty': 'Requesty',
  'upstage': 'Upstage',
  'vercel': 'Vercel',
  'zai': 'Zai',
};

// The order the accounts that are still learning are read in.
const CAPACITY_CHIPS = [
  'google',
  'requesty',
  'kilo',
  'nvidia',
  'groq',
  'cloudflare-workers-ai',
];

// The number a row holds, or nothing when the row holds no number.
function capacityNumber(value) {
  if (value === null || value === undefined || value === '') { return null; }
  const number = Number(value);
  return isFinite(number) ? number : null;
}

// The name an account is read by.
function capacityName(account) {
  const approved = CAPACITY_ACCOUNTS.find((entry) => entry.account === account);
  if (approved) { return approved.name; }
  if (CAPACITY_NAMES[account]) { return CAPACITY_NAMES[account]; }
  return String(account || '').split(/[-_\s]+/).filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
}

// The span of a duration, as a card writes it.
function capacitySpan(seconds) {
  const minutes = Math.round(Math.max(0, seconds) / 60);
  if (minutes < 60) { return minutes + 'm'; }
  if (minutes < 2880) { return Math.floor(minutes / 60) + 'h ' + (minutes % 60) + 'm'; }
  return (minutes / 1440).toFixed(1) + 'd';
}

// How long a window has left before it resets, or 'now' once it is due.
function capacityRelative(reset, now) {
  if (reset === null) { return ''; }
  const seconds = reset - now;
  if (seconds <= 0) { return 'now'; }
  return capacitySpan(seconds);
}

// The share that is left, with one decimal, so a card can be compared with
// the provider's own site: the half point of a reading is kept, and a whole
// reading keeps no trailing zero.
function capacityShare(left) {
  if (left === null) { return ''; }
  const tenths = Math.round(left * 1000);
  const text = tenths % 10 === 0 ? String(tenths / 10) : (tenths / 10).toFixed(1);
  return text + '%';
}

// The width of the bar of a window, in percent.
function capacityWidth(left) {
  if (left === null) { return ''; }
  return String(Math.round(left * 1000) / 10);
}

// The length a rolling window names, read from its label or its id.
function capacityRollingSpan(label, quotaId) {
  const parts = String(label || '').split('\u00b7');
  const tail = parts.length > 1 ? parts[parts.length - 1].trim() : '';
  if (tail) { return tail; }
  const identifier = String(quotaId || '');
  const index = identifier.indexOf(':');
  return index < 0 ? '' : identifier.slice(index + 1).trim();
}

// The windows of the accounts, read out of the rows of the page.
function capacityRead(rows) {
  const windows = new Map();
  const learning = [];
  const free = new Map();
  const availability = new Map();
  for (const row of rows || []) {
    if (!row || row.account === 'openrouter' || row.provider === 'openrouter') { continue; }
    if (row.field === 'reported_missing' && Number(row.value) === 1) {
      availability.set(row.account, {state:'unavailable', basis:'reported_unavailable', reason:'Reported limits unavailable · collector source read failed'});
      continue;
    }
    if (row.field === 'availability') {
      if (Number(row.value) === 1 && availability.get(row.account)?.basis !== 'reported_unavailable') { availability.set(row.account, row); }
      continue;
    }
    if (row.field === 'availability_checked') { continue; }
    if (row.field === 'free_models') {
      const provider = String(row.provider || '');
      const count = capacityNumber(row.value);
      if (provider && count !== null) {
        let entry = free.get(provider);
        if (!entry) { entry = { available: 0, unavailable: 0 }; free.set(provider, entry); }
        if (row.state === 'available') { entry.available = count; }
        else if (row.state === 'unavailable') { entry.unavailable = count; }
      }
      continue;
    }
    if (!row.account) { continue; }
    if (row.field === 'learning') {
      if (capacityNumber(row.value) === 1 && learning.indexOf(row.account) < 0) {
        learning.push(row.account);
      }
      continue;
    }
    const key = row.account + '|' + (row.kind || '') + '|' + (row.quota_id || '');
    let entry = windows.get(key);
    if (!entry) {
      entry = {
        account: row.account,
        kind: row.kind || '',
        paceDelta: null,
        paceState: null,
        reason: row.reason || '',
        quota_id: row.quota_id || '',
        label: row.label || '',
        evidence: row.evidence || '',
        left: null,
        expected: null,
        resetAt: null,
        checked: null,
        order: null,
        rolling: false,
      };
      windows.set(key, entry);
    }
    if (row.not_used === 'true') { entry.notUsed = true; }
    const value = capacityNumber(row.value);
    if (row.field === 'pace_delta') { entry.paceDelta = value; }
    if (row.field === 'pace_state' && value === 1) { entry.paceState = row.state; }
    if (row.field === 'left') { entry.left = value; }
    else if (row.field === 'expected') { entry.expected = value; }
    else if (row.field === 'resetAt') { entry.resetAt = value; }
    else if (row.field === 'checked') { entry.checked = value; }
    else if (row.field === 'order') { entry.order = value; }
    else if (row.field === 'rolling') { entry.rolling = value === 1; }
  }
  return { windows: Array.from(windows.values()), learning: learning, free: free, availability: availability };
}

// The pace of a window: how far it is from the share it expects to be left.
function capacityPace(left, state, longWindow, delta) {
  if (state === 'not_used') { return { word: 'Not used', cls: 'not_used', fill: 'not_used' }; }
  if (left === null) { return { word: '', cls: '', fill: '' }; }
  if (left <= 0) { return { word: '✕ spent', cls: 'spent', fill: 'spent' }; }
  if (!longWindow) { return { word: '', cls: '', fill: '' }; }
  const magnitude = delta === null || delta === undefined ? '' : (Math.round(Math.abs(delta) * 10) / 10) + ' ';
  const words = {ahead: '▲ ' + magnitude + 'ahead', on_pace: '● on pace', behind: '▼ ' + magnitude + 'behind', far_behind: '▼ ' + magnitude + 'behind'};
  return {word: words[state] || '', cls: state || '',
    fill: state === 'far_behind' ? 'spent' : state === 'behind' ? 'behind' : state === 'ahead' ? 'ahead' : ''};
}

// A reset time, read in UTC.
function capacityClock(reset) {
  if (reset === null) { return ''; }
  const moment = new Date(reset * 1000);
  if (isNaN(moment.getTime())) { return ''; }
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const pad = (n) => String(n).padStart(2, '0');
  return moment.getUTCDate() + ' ' + months[moment.getUTCMonth()] + ' ' + pad(moment.getUTCHours()) + ':' + pad(moment.getUTCMinutes());
}

// The free models of a provider, apart from its paid allowance: the line
// says how many are available, or that none of them is.
function capacityFreeLine(counts) {
  if (!counts) { return null; }
  const available = counts.available || 0;
  const unavailable = counts.unavailable || 0;
  if (available <= 0 && unavailable <= 0) { return null; }
  if (available > 0) {
    return {
      text: 'Free models \u00b7 available \u00b7 ' + available + ' models',
      cls: 'ok',
    };
  }
  return {
    text: 'Free models \u00b7 none available \u00b7 ' + unavailable + ' models',
    cls: '',
  };
}

// The age of the reading of a card, from its oldest window.
function capacityAge(now, checked) {
  if (checked === null) { return ''; }
  const seconds = now - checked;
  if (seconds < 60) { return 'read just now'; }
  return 'read ' + capacitySpan(seconds) + ' ago';
}

// One card: the account, its identity and its windows.
function capacityCard(account, entries, now, freeModels) {
  const approved = CAPACITY_ACCOUNTS.find((entry) => entry.account === account) || {};
  const name = capacityName(account);
  const ordered = entries.slice().sort((a, b) => {
    const first = a.order === null ? 99 : a.order;
    const second = b.order === null ? 99 : b.order;
    if (first !== second) { return first - second; }
    if (a.label === b.label) { return 0; }
    return a.label < b.label ? -1 : 1;
  });
  const checked = ordered
    .map((entry) => entry.checked)
    .filter((value) => value !== null);
  const oldest = checked.length ? Math.min.apply(null, checked) : null;
  const windows = ordered.map((entry) => {
    const longWindow = !/session|hour|daily|minute/i.test(entry.kind) && (/weekly|monthly|seven_day|week|month/i.test(entry.kind) || entry.expected !== null);
    const pace = capacityPace(entry.left, entry.notUsed ? 'not_used' : entry.paceState, longWindow, entry.paceDelta);
    const rolling = entry.rolling === true;
    const span = rolling ? capacityRollingSpan(entry.label, entry.quota_id) : '';
    const rollingText = rolling ? 'rolling' + (span ? ' ' + span : '') : '';
    const relative = capacityRelative(entry.resetAt, now);
    const resetText = relative === '' ? '' : (relative === 'now' ? 'resets now' : 'resets in ' + relative);
    const wide = [];
    const brief = [];
    if (rolling) {
      if (pace.word) { wide.push(pace.word); brief.push(pace.word); }
      wide.push(rollingText);
      brief.push(rollingText);
    } else {
      if (pace.word) { wide.push(pace.word); brief.push(pace.word); }
      if (resetText) {
        wide.push(relative === 'now' ? resetText : resetText + ' (' + capacityClock(entry.resetAt) + ')');
        brief.push(resetText);
      }
    }
    return {
      label: entry.label,
      notUsed: !!entry.notUsed || entry.paceState === 'not_used',
      inferred: entry.evidence === 'inferred',
      hasLeft: entry.left !== null || entry.unavailable,
      width: entry.unavailable ? '100' : capacityWidth(entry.left),
      pct: entry.unavailable ? 'Unavailable' : capacityShare(entry.left),
      fillClass: entry.notUsed ? 'not_used' : entry.unavailable ? 'unavailable' : pace.fill,
      hasTick: longWindow && entry.expected !== null && !rolling && !entry.notUsed && entry.paceState !== 'not_used',
      tick: entry.expected === null || rolling ? '' : String(Math.round(entry.expected * 1000) / 10),
      paceClass: entry.notUsed ? 'not_used' : entry.unavailable ? 'unavailable' : rolling ? '' : pace.cls,
      rolling: rolling,
      sub: entry.reason || wide.join(' \u00b7 '),
      brief: brief.join(' \u00b7 '),
    };
  });
  return {
    account: account,
    name: name,
    free: capacityFreeLine(freeModels),
    icon: approved.icon || name.charAt(0).toUpperCase(),
    background: approved.background || '#2b2f3a',
    foreground: approved.foreground || '#fff',
    meta: approved.meta || '',
    read: capacityAge(now, oldest),
    windows: windows,
  };
}

// The accounts of the page, in the order the owner approved.
function capacityOrder(accounts) {
  const rank = (account) => {
    const index = CAPACITY_ACCOUNTS.findIndex((entry) => entry.account === account);
    return index < 0 ? CAPACITY_ACCOUNTS.length : index;
  };
  return accounts.slice().sort((a, b) => {
    const first = rank(a);
    const second = rank(b);
    if (first !== second) { return first - second; }
    if (a === b) { return 0; }
    return capacityName(a) < capacityName(b) ? -1 : 1;
  });
}

context.handlebars.registerHelper('capacityCards', function (rows, now) {
  const read = capacityRead(rows);
  const accounts = [];
  const grouped = new Map();
  for (const entry of read.windows) {
    if (accounts.indexOf(entry.account) < 0) { accounts.push(entry.account); }
    if (!grouped.has(entry.account)) { grouped.set(entry.account, []); }
    grouped.get(entry.account).push(entry);
  }
  for (const [account, status] of read.availability) {
    if (accounts.indexOf(account) >= 0) { continue; }
    accounts.push(account);
    const available = status.state === 'available';
    grouped.set(account, [{account: account, label: available ?
      'no published limit' :
      (status.basis === 'reported_unavailable' ? 'Reported limits unavailable' : 'Unavailable'), left: available ? 1 : null, expected: null, resetAt: null,
      checked: null, order: 0, evidence: 'provider_reported', reason: status.reason || '', unavailable: !available}]);
  }
  const moment = capacityNumber(now);
  const seconds = moment === null ? 0 : moment / 1000;
  return capacityOrder(accounts).map((account) => capacityCard(
    account,
    grouped.get(account) || [],
    seconds,
    read.free.get(account),
  ));
});

context.handlebars.registerHelper('utcStamp', function (value) {
  // The as-of time in UTC, from the dashboard's end time in epoch milliseconds.
  // Only a number is formatted here; no label text is read.
  const moment = new Date(Number(value));
  if (isNaN(moment.getTime())) { return ''; }
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const pad = (n) => String(n).padStart(2, '0');
  return moment.getUTCDate() + ' ' + months[moment.getUTCMonth()] + ' ' + pad(moment.getUTCHours()) + ':' + pad(moment.getUTCMinutes());
});

